import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;

public class TagTest {

    @Test
    public void getName_EmptyName_ReturnsEmptyString() {
        Tag tag = new Tag();
        assertEquals("", tag.getName());
    }

    @Test
    public void getName_NonEmptyName_ReturnsCorrectName() {
        Tag tag = new Tag();
        tag.setName("test");
        assertEquals("test", tag.getName());
    }

    @Test
    public void normalName_EmptyName_ReturnsEmptyString() {
        Tag tag = new Tag();
        assertEquals("", tag.normalName());
    }

    @Test
    public void normalName_NonEmptyName_ReturnsCorrectNormalizedName() {
        Tag tag = new Tag();
        tag.setName("test");
        assertEquals(Validate.uniq, tag.normalName());
    }

    @Test
    public void valueOf_EmptyTagname_ThrowsNullPointerException() {
        ParseSettings settings = new ParseSettings();
        assertThrows(NullPointerException.class, () -> Tag.valueOf("", settings));
    }

    @Test
    public void valueOf_NonEmptyTagname_ReturnsCorrectTag() {
        ParseSettings settings = new ParseSettings();
        Tag tag = Tag.valueOf("test", settings);
        assertNotNull(tag);
        assertEquals("test", tag.getName());
    }

    @Test
    public void isBlock_DefaultTagsAreBlocks() {
        assertTrue(Tag.isBlock("a"));
        assertFalse(Tag.isBlock("img"));
    }

    @Test
    public void isInline_DefaultTagsAreInlines() {
        assertTrue(Tag.isInline("span"));
        assertFalse(Tag.isInline("table"));
    }

    @Test
    public void isEmpty_DivTagIsNotEmpty() {
        assertFalse(Tag.isEmpty("div"));
    }

    @Test
    public void isEmpty_SelfClosingTagIsNotEmpty() {
        assertTrue(Tag.isSelfClosing("img"));
    }

    @Test
    public void isKnownTag_ReturnsFalseForUnknownTags() {
        assertFalse(Tag.isKnownTag("unknown"));
    }

    @Test
    public void isFormListed_FormTagsAreFormListed() {
        assertTrue(Tag.isFormListed("form"));
    }

    @Test
    public void isFormSubmittable_InputTagsAreFormSubmittable() {
        assertTrue(Tag.isFormSubmittable("input"));
    }

    @Test
    public void setSelfClosing_SelfClosingTagSetsAsSelfClosing() {
        Tag tag = new Tag();
        tag.setSelfClosing();
        assertTrue(tag.isSelfClosing());
    }
}
